<original_code>
#include <iostream>
#include <string>
#include <cstdlib>
#include <vector>
#include <cmath>
using namespace std;

typedef long long number_type;
#define size_of_container(c) (int)(c).size()

number_type compute_gcd(number_type a, number_type b) {
    while( b != 0 )
        a %= b, swap(a, b);
    return a;
}

int main() {
    number_type a, b, max_b; cin >> a >> b >> max_b;
    number_type bestA, bestB;
    double minDifference = 1e12;
    for(number_type b_value = 1; b_value <= max_b; b_value++) {
        number_type left = 0, right = 100000;
        number_type a_candidate = 0;
        while( left <= right ) {
            number_type mid = (left + right) >> 1;
            if( mid * b <= a * b_value )
                a_candidate = mid, left = mid + 1;
            else
                right = mid - 1;
        }
        left = 0, right = 100000;
        number_type a2_candidate = 0, b2_candidate = b_value;
        while( left <= right ) {
            number_type mid = (left + right) >> 1;
            if( mid * b < a * b_value )
                left = mid + 1;
            else
                a2_candidate = mid, right = mid - 1;
        }
        double diff2 = abs(double(a2_candidate)/double(b2_candidate) - double(a)/double(b));
        double diff1 = abs(double(a_candidate)/double(b_value) - double(a)/double(b));
        if( diff2 + 1e-8 < diff1)
            a_candidate = a2_candidate, b2_candidate = b2_candidate, diff1 = diff2;
        number_type g = compute_gcd(a_candidate, b2_candidate);
        if( diff1 < minDifference )
            bestA = a_candidate / g, bestB = b2_candidate / g, minDifference = diff1;
    }
    cout << bestA << "/" << bestB;
    return 0;
}
